	case "init":
		return store.Init()
	case "put":
		entry, err := store.Put(*name, *file)
		if err == nil {
			fmt.Printf("stored %s sha256=%s size=%d\n", entry.Name, entry.Digest, entry.Size)
		}
		return err
	case "get":
		return store.Get(*name, *output)
