}

func TestSnapshotCreateFailsOnCorruptedIndex(t *testing.T) {
	store := New(filepath.Join(t.TempDir(), "vault"))
	putString(t, store, "a", "1")
	if err := os.WriteFile(store.indexPath(), []byte("{broken"), 0o644); err != nil {
